import unittest
from app import total
class Tests(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total('1,2,3'), 6)

class CliTests(unittest.TestCase):
    def run_cli(self, *args):
        import pathlib
        import subprocess
        import sys
        return subprocess.run(
            [sys.executable, str(pathlib.Path(__file__).with_name('app.py')), *args],
            capture_output=True, text=True,
        )

    def test_invalid_numbers(self):
        for value in ('1,,2', ',1', '1,', '', '1,x,2'):
            with self.subTest(value=value):
                result = self.run_cli(value)
                self.assertEqual(result.returncode, 2)
                self.assertEqual(result.stdout, '')
                self.assertIn('error:', result.stderr)
                self.assertIn('comma-separated integers', result.stderr)
                self.assertNotIn('Traceback', result.stderr)

    def test_valid_numbers(self):
        for value, expected in (('1,2,3', '6\n'), ('1,-2,0', '-1\n'), (' 1, 2 ', '3\n')):
            with self.subTest(value=value):
                result = self.run_cli(value)
                self.assertEqual(result.returncode, 0)
                self.assertEqual(result.stdout, expected)
                self.assertEqual(result.stderr, '')

    def test_help(self):
        result = self.run_cli('--help')
        self.assertEqual(result.returncode, 0)
        self.assertIn('Sum comma-separated integers.', result.stdout)
        self.assertEqual(result.stderr, '')

    def test_missing_argument(self):
        result = self.run_cli()
        self.assertEqual(result.returncode, 2)
        self.assertIn('required', result.stderr)
        self.assertNotIn('Traceback', result.stderr)

if __name__ == '__main__': unittest.main()
